const listAccessLog = `-- name: ListAccessLog :many
SELECT l.id, l.user_id, l.api_key_id, l.agent_id, l.agent_version_id, l.rank, l.channel, l.at, coalesce(u.email, '')::text AS user_email, coalesce(u.display_name, '')::text AS user_name,
       coalesce(a.name, '')::text AS agent_name, coalesce(a.slug, '')::text AS agent_slug,
       coalesce(t.slug, '')::text AS team_slug, v.version AS agent_version,
       coalesce(cl.key, '')::text AS classification
FROM access_log l
LEFT JOIN users u ON u.id = l.user_id
LEFT JOIN agents a ON a.id = l.agent_id
LEFT JOIN teams t ON t.id = a.team_id
LEFT JOIN agent_versions v ON v.id = l.agent_version_id
LEFT JOIN classification_levels cl ON cl.rank = l.rank
WHERE ($1::timestamptz IS NULL OR l.at >= $1::timestamptz)
  AND ($2::timestamptz IS NULL OR l.at < $2::timestamptz)
  AND ($3::uuid IS NULL OR l.agent_id = $3::uuid)
  AND ($4::uuid IS NULL OR l.user_id = $4::uuid)
  AND ($5::text IS NULL OR l.channel = $5::text)
  AND ($6::timestamptz IS NULL
       OR (l.at, l.id) < ($6::timestamptz, $7::bigint))
ORDER BY l.at DESC, l.id DESC
LIMIT $8
`

