const listConversations = `-- name: ListConversations :many
SELECT c.id, c.agent_id, c.user_id, c.title, c.last_version_id, c.created_at, c.updated_at, c.deleted_at, c.anonymous, c.anon_session_id, a.name AS agent_name, a.slug AS agent_slug, t.slug AS team_slug,
       (a.deleted_at IS NOT NULL)::bool AS agent_deleted
FROM conversations c
JOIN agents a ON a.id = c.agent_id
JOIN teams t ON t.id = a.team_id
WHERE c.user_id = $1::uuid AND c.deleted_at IS NULL
  AND ($2::uuid IS NULL OR c.agent_id = $2::uuid)
  -- A personal API key reaches its team's agents only, or the ones it names.
  AND ($3::uuid IS NULL OR a.team_id = $3::uuid)
  AND ($4::uuid[] IS NULL OR c.agent_id = ANY($4::uuid[]))
  AND ($5::text IS NULL
       OR (c.title || ' ' || a.name) ILIKE '%' || $5::text || '%' ESCAPE '\')
  AND ($6::timestamptz IS NULL OR c.updated_at >= $6::timestamptz)
  AND ($7::timestamptz IS NULL OR c.updated_at < $7::timestamptz)
  AND ($8::timestamptz IS NULL
       OR (c.updated_at, c.id) < ($8::timestamptz, $9::uuid))
ORDER BY c.updated_at DESC, c.id DESC
LIMIT $10
`

