const versionsByIDs = `-- name: VersionsByIDs :many
SELECT id, agent_id, version, config, chat_model_id, effective_rank, note, published_by, published_at FROM agent_versions WHERE id = ANY($1::uuid[])
`

func (q *Queries) VersionsByIDs(ctx context.Context, ids []uuid.UUID) ([]AgentVersion, error) {
	rows, err := q.db.Query(ctx, versionsByIDs, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AgentVersion{}
	for rows.Next() {
		var i AgentVersion
		if err := rows.Scan(
			&i.ID,
			&i.AgentID,
			&i.Version,
			&i.Config,
			&i.ChatModelID,
			&i.EffectiveRank,
			&i.Note,
			&i.PublishedBy,
			&i.PublishedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
